-- 연산자들

List<Member> findByAgeBetween(int from, int to);
List<Member> findByAgeLessThanEqual(int age);
List<Member> findByUsernameLike(String pattern);
List<Member> findByUsernameStartingWith(String prefix);
List<Member> findByUsernameContaining(String part);
List<Member> findByTeamIsNull();
List<Member> findByUsernameIn(Collection<String> names);
List<Member> findByUsernameIgnoreCase(String username);

@Test
@Transactional
void 연산자들() {
    em.clear(); memberRepository.findByAgeBetween(10, 20);
    em.clear(); memberRepository.findByUsernameStartingWith("m");
    em.clear(); memberRepository.findByUsernameContaining("1");
    em.clear(); memberRepository.findByTeamIsNull();
    em.clear(); memberRepository.findByUsernameIgnoreCase("M1");
}

