-- 중첩 속성은 조인이다

List<Member> findByTeamName(String name);

@Test
@Transactional
void 중첩() {
    em.clear();
    memberRepository.findByTeamName("A팀");
}

Hibernate:
    select
        m1_0.member_id,
        m1_0.age,
        m1_0.team_id,
        m1_0.username
    from
        member m1_0
    join
        team t1_0
            on t1_0.team_id=m1_0.team_id
    where
        t1_0.name=?

--   inner join 이다
--   4.4절의 정렬은 left join 이었다
--   조건이면 inner 다


